router.get('/orders', async (req, res, next) => {
  try {
    const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);

    let createdAt = null;
    let id = null;
    if (req.query.cursor) {
      try {
        [createdAt, id] = JSON.parse(Buffer.from(req.query.cursor, 'base64url').toString());
      } catch {
        return res.status(400).json({ error: 'Invalid cursor' });
      }
    }

    // created_at::text keeps microseconds, which a JS Date would truncate and break the keyset comparison.
    // Fetch one extra row to know whether there is a next page.
    const { rows } = await pool.query(
      `SELECT o.*, o.created_at::text AS cursor_ts
         FROM orders o
        WHERE $1::timestamptz IS NULL OR (o.created_at, o.id) < ($1::timestamptz, $2)
        ORDER BY o.created_at DESC, o.id DESC
        LIMIT $3`,
      [createdAt, id, limit + 1]
    );

    const hasMore = rows.length > limit;
    const page = rows.slice(0, limit);
    const last = page[page.length - 1];

    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: hasMore
        ? Buffer.from(JSON.stringify([last.cursor_ts, last.id])).toString('base64url')
        : null,
    });
  } catch (err) {
    next(err);
  }
});
```

This assumes `pool` is your `pg` Pool and needs `CREATE INDEX ON orders (created_at DESC, id DESC);` to stay fast.
